clear; 
clc; 
format longEng


% Parametreler 


L = 1; 
H = 1;
nx = input('Lütfen nxn boyutunda ızgara değerini giriniz: ');
ny = nx;
dx = L / nx; 
dy = H / ny;


% Akışkan Özellikleri


Ra = input('istenen Railegh sayısı değerini giriniz:');
Pr = input('Akışkanın Prandtl sayısı değerini giriniz:');


% Staggered Grid


u = zeros(nx+1, ny); % x-hızları: i=1 (sol duvar), i=nx+1 (sağ duvar)
v = zeros(nx, ny+1); % y-hızları: j=1 (alt duvar), j=ny+1 (üst duvar(kapak))
p = zeros(nx, ny);   % Basınç: Merkezlerde
tetha = 0.5 * ones(nx, ny); % Sıcaklık: Merkezlerde


d_tav = 1e-3;


tetha_sol = 1;
tetha_sag = 0;


d_u = zeros(nx+1, ny);
d_v = zeros(nx, ny+1);




% Zaman Adımı için Döngü 


max_zaman_adimi = 5000;
epsilon_zaman = 1e-6;
Nu_eski_zaman = 0;




for n_step = 1:max_zaman_adimi %[output:group:8dcdd862]


    u_n = u;
    v_n = v;
    tetha_n = tetha;


% SIMPLE Algoritması


epsilon_s = 1e-8; 
max_iter = 100;


alpha_p = 0.3; 
alpha_u = 0.5;
alpha_t = 0.6;


hata = 1; 
iter = 0;


while hata > epsilon_s && iter < max_iter
    iter = iter + 1;
    
    u_eski = u; 
    v_eski = v;
    tetha_eski = tetha;


    u_gecici = u; 
    v_gecici = v;
    tetha_gecici = tetha;


    % Enerji Denklemi
    for i = 1:nx
        for j = 1:ny


            D_w = dy / dx; 
            D_e = dy / dx;
            D_s = dx / dy; 
            D_n = dx / dy;


            % Sağ/Sol Yüzeylerdeki Konvektif Akılar (Flux)


            if i == 1
                F_w = 0;
                F_e = 0.5 * dy * (u(i+1, j) + u(i, j));
            elseif i == nx 
                F_e = 0;
                F_w = 0.5 * dy * (u(i, j) + u(i-1, j));
            else
                F_w = 0.5 * dy * (u(i, j) + u(i-1, j));
                F_e = 0.5 * dy * (u(i+1, j) + u(i, j));
            end


            % Alt/Üst yüzeylerdeki Konvektif Akılar (Flux)


            if i == 1
               
                if j == 1
                    F_s = 0; % Alt duvar
                    F_n = 0.5 * dx * v(i, j+1);
                elseif j == ny
                    F_s = 0.5 * dx * v(i, j);
                    F_n = 0; % Üst duvar
                else
                    F_s = 0.5 * dx * v(i, j);
                    F_n = 0.5 * dx * v(i, j+1);
                end
            else
                % i > 1 iç hücreler için
                if j == 1
                    F_s = 0; % Alt duvar
                    F_n = 0.5 * dx * (v(i-1, j+1) + v(i, j+1));
                elseif j == ny
                    F_s = 0.5 * dx * (v(i-1, j) + v(i, j));
                    F_n = 0; % Üst duvar
                else
                    F_s = 0.5 * dx * (v(i-1, j) + v(i, j));
                    F_n = 0.5 * dx * (v(i-1, j+1) + v(i, j+1));
                end
            end


            % Katsayılar 


            a_w = D_w + max(F_w, 0);
            a_e = D_e + max(-F_e, 0);
            a_s = D_s + max(F_s, 0);
            a_n = D_n + max(-F_n, 0);
            a0_p = ( dx * dy ) / d_tav;


            b_kaynak = a0_p * tetha_n(i, j); % sadece fiziksel zaman adımı


            % Duvar Kaymamazlık Sınır Koşulları 


            % Yan Duvarlar (w ve e)


            if i == 1
                a_w = 0; % sol komşu yok 
                a_ij_duvar = 2 * D_w + max(F_w, 0);
                b_kaynak = b_kaynak + (2 * D_w + max(F_w, 0)) * tetha_sol; % sol duvar tetha = 1 
            elseif i == nx
                a_e = 0;
                a_ij_duvar = 2 * D_e + max(-F_e, 0);
                b_kaynak = b_kaynak + (2 * D_e + max(-F_e, 0)) * tetha_sag; % sağ duvar tetha = 0
            end


            % Alt ve Üst Duvarlar (s ve n)


            if j == 1
                a_s = 0; % Alt duvardan iletimsel ısı geçişi yok (adyabatik)
            end 


            if j == ny
                a_n = 0; % Üst duvardan iletimsel ısı geçişi yok (adyabatik) 
            end


            a_ij = a_w + a_e + a_s + a_n + a0_p;
            if i == 1,  a_ij = a_ij + (2 * D_w + max(F_w, 0)); end
            if i == nx, a_ij = a_ij + (2 * D_e + max(-F_e, 0)); end


            % Komşu Sıcaklıkların Toplamı
            top_komsu = 0;


            if i > 1,  top_komsu = top_komsu + a_w * tetha(i-1, j); end
            if i < nx, top_komsu = top_komsu + a_e * tetha(i+1, j); end
            if j > 1,  top_komsu = top_komsu + a_s * tetha(i, j-1); end
            if j < ny, top_komsu = top_komsu + a_n * tetha(i, j+1); end


            tetha_gecici(i, j) = (top_komsu + b_kaynak) / a_ij;


            tetha(i, j) = tetha_gecici(i, j);


        end 
    end


    % x-Momentum Denklemi (u hızı için) 
    for i = 2:nx
        for j = 1:ny


            D_w = Pr * dy / dx; 
            D_e = Pr * dy / dx;
            D_s = Pr * dx / dy; 
            D_n = Pr * dx / dy;
            
            % Konvektif Akılar (Flux)


            F_w = 0.5 * dy * (u(i, j) + u(i-1, j));
            F_e = 0.5 * dy * (u(i+1, j) + u(i, j));
            
            % Alt/Üst yüzeylerdeki Konvektif Akılar (Flux)


            if j == 1
                F_s = 0; % Alt duvar
                F_n = 0.5 * dx * (v(i-1, j+1) + v(i, j+1));


            elseif j == ny
                F_s = 0.5 * dx * (v(i-1, j) + v(i, j));
                F_n = 0; % Üst duvar


            else


                F_s = 0.5 * dx * (v(i-1, j) + v(i, j));
                F_n = 0.5 * dx * (v(i-1, j+1) + v(i, j+1));


            end
            
            % Katsayılar 


            a_w = D_w + max(F_w, 0);
            a_e = D_e + max(-F_e, 0);
            a_s = D_s + max(F_s, 0);
            a_n = D_n + max(-F_n, 0);
            a0_p = dx * dy / d_tav;
            
            b_kaynak = a0_p * u_n(i, j);   
            
            % Duvar Kaymamazlık Sınır Koşulları 


            % Yan Duvarlar (w ve e)


            if i == 2
                a_w = 2 * D_w + max(F_w, 0);
            elseif i == nx
                a_e = 2 * D_e + max(-F_e, 0);
            end


            % Alt ve Üst Duvarlar (s ve n)


            if j == 1
                a_s = 2 * D_s + max(F_s, 0); 
            end 
            
            if j == ny
                a_n = 2 * D_n + max(-F_n, 0); 
            end
            
            a_ij = a_w + a_e + a_s + a_n + a0_p;
            p_hesap = (p(i-1, j) - p(i, j)) * dy;
            


            u_s = 0; u_north = 0;
            if j > 1, u_s = u(i, j-1); end
            if j < ny, u_north = u(i, j+1); end
            
            top_komsu = a_w*u(i-1, j) + a_e*u(i+1, j) + a_s*u_s + a_n*u_north; 
            
            u_gecici(i, j) = (top_komsu + p_hesap + b_kaynak) / a_ij;


            d_u(i, j) = dy / a_ij;


        end
    end
    
    % y-Momentum Denklemi (v hızı için)
    for i = 1:nx
        for j = 2:ny


            D_w = Pr * dy / dx; 
            D_e = Pr * dy / dx;
            D_s = Pr * dx / dy; 
            D_n = Pr * dx / dy;
            
            % Konvektif Akılar (Flux)


            if i == 1
                F_w = 0;
                F_e = 0.5 * dy * (u(i+1, j-1) + u(i+1, j));
            elseif i == nx
                F_w = 0.5 * dy * (u(i, j-1) + u(i, j));
                F_e = 0;
            else
                F_w = 0.5 * dy * (u(i, j-1) + u(i, j));
                F_e = 0.5 * dy * (u(i+1, j-1) + u(i+1, j));
            end
            
            F_s = 0.5 * dx * (v(i, j) + v(i, j-1));
            F_n = 0.5 * dx * (v(i, j+1) + v(i, j));


            % Katsayılar 
            
            a_w = D_w + max(F_w, 0);
            a_e = D_e + max(-F_e, 0);
            a_s = D_s + max(F_s, 0);
            a_n = D_n + max(-F_n, 0);
            a0_p = dx * dy / d_tav;


            if i == 1
                tetha_v = 0.5 * (tetha_sol + 0.5*(tetha(i, j-1) + tetha(i, j)));
            elseif i == nx
                tetha_v = 0.5 * (tetha_sag + 0.5*(tetha(i, j-1) + tetha(i, j)));
            else
                tetha_v = 0.5 * (tetha(i, j-1) + tetha(i, j));
            end


            b_boussinesq = Ra * Pr * tetha_v * dx * dy;
            b_kaynak = b_boussinesq + (a0_p * v_n(i, j));
            
            % Duvar Kaymamazlık Sınır Koşulları


            if i == 1
                a_w = a_w + 2*D_w;
            end


            if i == nx
                a_e = a_e + 2*D_e;
            end


            % Alt ve Üst Duvarlar (s ve n)


            if j == 2
                a_s = 2 * D_s + max(F_s, 0); 
            end 


            if j == ny
                a_n = 2 * D_n + max(-F_n, 0); 
            end
            
            a_ij = a_w + a_e + a_s + a_n + a0_p;
            p_hesap = (p(i, j-1) - p(i, j)) * dx;
            
            v_w = 0; v_e = 0;
            if i > 1, v_w = v(i-1, j); end 
            if i < nx, v_e = v(i+1, j); end 
            
            top_komsu = a_w*v_w + a_e*v_e + a_s*v(i, j-1) + a_n*v(i, j+1);
            
            v_gecici(i, j) = (top_komsu + p_hesap + b_kaynak) / a_ij;


            d_v(i, j) = dx / a_ij;
        end
    end
    
    % 3. Süreklilik (Kütle Hatası)


    b = zeros(nx, ny);


    for i = 1:nx
        for j = 1:ny


            b(i, j) = (u_gecici(i, j) - u_gecici(i+1, j)) * dy + (v_gecici(i, j) - v_gecici(i, j+1)) * dx;
                      
        end
    end
    
    % 4. Basınç Düzeltme Denklemi


    p_duzeltme = zeros(nx, ny);


    for k = 1:150
        for i = 1:nx
            for j = 1:ny


                ap_w = 0; 
                ap_e = 0; 
                ap_s = 0; 
                ap_n = 0;
                
                if i > 1
                    ap_w = d_u(i, j) * dy;
                end


                if i < nx
                    ap_e = d_u(i+1, j) * dy;
                end


                if j > 1
                    ap_s = d_v(i, j) * dx;
                end


                if j < ny
                    ap_n = d_v(i, j+1) * dx;
                end
                
                ap_top = ap_w + ap_e + ap_s + ap_n;
                
                % Sınır Koşullarına göre Düzenleme


                p_w = 0; 
                if i > 1
                    p_w = p_duzeltme(i-1, j); 
                end


                p_e = 0; 
                if i < nx
                    p_e = p_duzeltme(i+1, j); 
                end


                p_s = 0; 
                if j > 1
                    p_s = p_duzeltme(i, j-1);
                end


                p_n = 0;
                 if j < ny
                     p_n = p_duzeltme(i, j+1); 
                 end                
                         
                % Basınç Değerinin Bir Noktada Sabitlenmesi


                if i == round(nx / 2)  && j == round(ny / 2)
                    p_duzeltme(i, j) = 0;
                else
                    p_duzeltme(i, j) = (ap_w*p_w + ap_e*p_e + ap_s*p_s + ap_n*p_n + b(i, j)) / ap_top;
                end
            end
        end
    end
    
    % 5. Değişkenleri Güncelle
    p = p + alpha_p * p_duzeltme;
    p = p - p(round(nx / 2), round(ny / 2)); % Tüm basınç alanının referans noktasına göre sıfırlanması


    % T Sıcaklık Güncelleme 


    tetha = tetha_gecici;
    
    % U Hızı Güncelleme


    for i = 2:nx
        for j = 1:ny
            u(i, j) = alpha_u * (u_gecici(i, j) + d_u(i, j) * (p_duzeltme(i-1, j) - p_duzeltme(i, j))) + (1 - alpha_u) * u_eski(i, j);
        end
    end
    
    % V Hızı Güncelleme


    for i = 1:nx
        for j = 2:ny
            v(i, j) = alpha_u * (v_gecici(i, j) + d_v(i, j) * (p_duzeltme(i, j-1) - p_duzeltme(i, j))) + (1 - alpha_u) * v_eski(i, j);
        end
    end
    
    % Maksimum Kütle Hatası
    hata = max(abs(b(:)));
    
end


% Kararlı Rejim Kontrolü (Nu Sayısı Kontrolü ve Zaman Adımı Yakınsaması)


fark_tetha = max(abs(tetha(:) - tetha_n(:)));
fark_u     = max(abs(u(:) - u_n(:)));
fark_v     = max(abs(v(:) - v_n(:)));


if rem(n_step, 100) == 0 || n_step == 1
    fprintf('Zaman Adımı: %d | d_tetha: %e | d_u: %e\n', n_step, fark_tetha, fark_u); %[output:07ab6a59]
end


if fark_tetha < 1e-6 && fark_u < 1e-6 && fark_v < 1e-6
    fprintf('SİSTEM KARARLI REJİME ULAŞTI (Zaman Adımı: %d)\n', n_step); %[output:5efe3798]
    break;
end


end %[output:group:8dcdd862]


% Görselleştirme
x_gorsel = linspace(0, L, nx);
y_gorsel = linspace(0, H, ny);
[X, Y] = meshgrid(x_gorsel, y_gorsel); 


u_merkez = zeros(nx, ny);
v_merkez = zeros(nx, ny);


for i = 1:nx
    for j = 1:ny
        u_merkez(i, j) = 0.5 * (u(i, j) + u(i+1, j));
        v_merkez(i, j) = 0.5 * (v(i, j) + v(i, j+1));
    end
end


% meshgrid ile uyumlu olması için matrislerin transpozu 


u_plot = u_merkez';
v_plot = v_merkez';
p_plot = p'; 
tetha_plot = tetha';


% Akım Çizgileri


figure(1); %[output:4e3bbfeb]
clf; %[output:4e3bbfeb]
hold on; %[output:4e3bbfeb]
streamslice(X, Y, u_plot, v_plot); %[output:4e3bbfeb]
rectangle('Position', [0, 0, L, H], 'LineWidth', 2, 'EdgeColor', 'k'); %[output:4e3bbfeb]
title(['Natural Convection in Square Enclosure Akım Çizgileri (Ra = ', num2str(Ra), ', Pr = ', num2str(Pr), ')']); %[output:4e3bbfeb]
xlabel('L (m)'); %[output:4e3bbfeb]
ylabel('H (m)'); %[output:4e3bbfeb]
axis equal;  %[output:4e3bbfeb]
xlim([0 L]); %[output:4e3bbfeb]
ylim([0 H]); %[output:4e3bbfeb]
hold off; %[output:4e3bbfeb]


% Basınç Dağılımı


figure(2); %[output:396a05d5]
clf; %[output:396a05d5]
hold on; %[output:396a05d5]
contourf(X, Y, p_plot, 21, 'LineColor', 'none'); %[output:396a05d5]
colorbar;colormap('jet');  %[output:396a05d5]
rectangle('Position', [0, 0, L, H], 'LineWidth', 2, 'EdgeColor', 'k'); %[output:396a05d5]
title(['Basınç Dağılımı (Ra = ', num2str(Ra), ')']); %[output:396a05d5]
xlabel('L (m)'); ylabel('H (m)'); %[output:396a05d5]
xlim([0 L]); ylim([0 H]); %[output:396a05d5]
axis equal; %[output:396a05d5]
hold off; %[output:396a05d5]




% Hız Büyüklüğü Dağılımı


V_merkez = sqrt(u_merkez.^2 + v_merkez.^2);
V_plot = V_merkez';


figure(3); %[output:0263d010]
clf; %[output:0263d010]
hold on; %[output:0263d010]
contourf(X, Y, V_plot, 21, 'LineColor', 'none'); %[output:0263d010]
colorbar;colormap('jet'); %[output:0263d010]
rectangle('Position', [0, 0, L, H], 'LineWidth', 2, 'EdgeColor', 'k'); %[output:0263d010]
title(['Hız Dağılımı (Büyüklük) (Ra = ', num2str(Ra), ')']); %[output:0263d010]
xlabel('L (m)'); ylabel('H (m)'); %[output:0263d010]
xlim([0 L]); ylim([0 H]); %[output:0263d010]
axis equal; %[output:0263d010]
hold off; %[output:0263d010]


% Sıcaklık Dağılımı 
figure(4); %[output:81233a35]
clf; %[output:81233a35]
hold on; %[output:81233a35]
contourf(X, Y, tetha_plot, 21, 'LineColor', 'none'); %[output:81233a35]
colorbar; colormap('jet'); %[output:81233a35]


adim = 3;
X_sub = X(1:adim:end, 1:adim:end);
Y_sub = Y(1:adim:end, 1:adim:end);
u_sub = u_plot(1:adim:end, 1:adim:end);
v_sub = v_plot(1:adim:end, 1:adim:end);
quiver(X_sub, Y_sub, u_sub, v_sub, 0.8, 'r', 'LineWidth', 1.0); %[output:81233a35]
rectangle('Position', [0, 0, L, H], 'LineWidth', 2, 'EdgeColor', 'k'); %[output:81233a35]
title(['Sıcaklık Dağılımı (\theta) (Ra = ', num2str(Ra), ')']); %[output:81233a35]
xlabel('L (m)'); ylabel('H (m)'); %[output:81233a35]
xlim([0 L]); ylim([0 H]); %[output:81233a35]
axis equal; %[output:81233a35]
hold off; %[output:81233a35]


% Sol Duvar Boyunca Yerel Nusselt Sayısı (Nu_y)
Nu_y = zeros(1, ny);

% Sol duvarın tamamında tutarlı 2. derece ileri fark türevi
for j = 1:ny
    Nu_y(j) = (8*tetha_sol - 9*tetha(1, j) + tetha(2, j)) / (3 * dx);
end


% Ortalama Nusselt Sayısı ve Maksimum Hızlar
Nu_ort = trapz(y_gorsel, Nu_y) / H;% Aritmetik ortalama yerine Yamuk Kuralı (Trapezoidal Rule) ile integral
u_max = max(abs(u_merkez(:)));
v_max = max(abs(v_merkez(:)));




% Referans Değerler (de Vahl Davis, 1983 - Ra = 10^4)
Nu_ref = 2.2430;
u_max_ref = 16.1780;
v_max_ref = 19.6170;




% Yüzde Bağıl Hata Hesapları (%)
hata_Nu = abs(Nu_ort - Nu_ref) / Nu_ref * 100;
hata_u  = abs(u_max - u_max_ref) / u_max_ref * 100;
hata_v  = abs(v_max - v_max_ref) / v_max_ref * 100;




% Benchmark Tablosu
fprintf('\n Ra = 10^4 için Benchmark Tablosu\n'); %[output:37047c82]
fprintf('Parametre                   | Kodun Sonucu | Ref (de Vahl Davis) | Hata (%%)\n'); %[output:51e17b91]
fprintf('Ortalama Nusselt (Nu_ort)   | %12.4f | %19.4f | %8.2f%%n', Nu_ort, Nu_ref, hata_Nu); %[output:3184fe3a]
fprintf('Maksimum u Hızı (u_max)     | %12.4f | %19.4f | %8.2f%%n', u_max, u_max_ref, hata_u); %[output:0027f01b]
fprintf('Maksimum v Hızı (v_max)     | %12.4f | %19.4f | %8.2f%%n', v_max, v_max_ref, hata_v); %[output:8245d92f]




% Sol Duvar Boyunca Nu_y(y) Değişim Grafiği
figure(5); clf; %[output:5dcd6d86]
plot(y_gorsel, Nu_y, 'b-o', 'LineWidth', 1.5, 'MarkerSize', 4); %[output:5dcd6d86]
grid on; %[output:5dcd6d86]
title(['Sol Duvarda Yerel Nusselt Sayısı Değişimi Nu_y(y) (Ra = ', num2str(Ra), ')']); %[output:5dcd6d86]
xlabel('Yükseklik (H)'); %[output:5dcd6d86]
ylabel('Yerel Nusselt Sayısı (Nu_y)'); %[output:5dcd6d86]
xlim([0 H]); %[output:5dcd6d86]



